    <style>
        :root{--ink:#172033;--muted:#687386;--blue:#2563eb;--line:#e5eaf2;--canvas:#f7f9fc}*{box-sizing:border-box}body{margin:0;min-height:100vh;color:var(--ink);background:var(--canvas);font-family:"DM Sans",sans-serif}.wrap{min-height:100vh;display:grid;grid-template-columns:1fr 1fr;max-width:1440px;margin:auto}.story{padding:clamp(36px,7vw,100px);display:flex;flex-direction:column;justify-content:space-between;background:linear-gradient(145deg,#edf4ff 0%,#f7f9fc 62%)}.brand{display:flex;align-items:center;gap:12px;font-weight:800}.mark{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;color:#fff;background:var(--blue);box-shadow:0 8px 18px #2563eb33}.story h1{max-width:520px;margin:0;font:800 clamp(40px,5vw,70px)/1.03 Manrope,sans-serif;letter-spacing:-.06em}.story p{max-width:480px;color:var(--muted);font-size:18px}.quote{color:#526076;font-size:13px}.panel{display:grid;place-items:center;padding:32px}.card{width:min(100%,440px);padding:42px;border:1px solid var(--line);border-radius:24px;background:#fff;box-shadow:0 24px 70px #1e315314}.eyebrow{color:var(--blue);font-size:12px;font-weight:700;letter-spacing:.13em;text-transform:uppercase}.card h2{margin:12px 0 9px;font:800 30px/1.1 Manrope,sans-serif;letter-spacing:-.05em}.muted{color:var(--muted);font-size:14px;line-height:1.6}.google{display:flex;align-items:center;justify-content:center;gap:11px;min-height:50px;margin-top:28px;border-radius:11px;color:#fff;background:var(--blue);font-weight:700;text-decoration:none;transition:.18s ease}.google:hover{background:#1749b3;transform:translateY(-2px)}.notice{margin-top:18px;padding:13px 14px;border-radius:10px;background:#fff7ed;color:#9a4d0b;font-size:12px;line-height:1.5}.foot{margin-top:28px;color:#8a94a5;font-size:12px}@media(max-width:760px){.wrap{display:block}.story{min-height:330px;padding:30px}.story h1{font-size:43px;margin-top:55px}.story p{font-size:15px}.quote{display:none}.panel{padding:22px 16px}.card{padding:30px 24px}}
